from math import gcd
from functools import reduce

def find_sequence(n, k):
    if n < k or n % k != 0:
        return -1

    target_gcd = n // k
    sequence = [target_gcd] * k

    current_sum = sum(sequence)
    remaining = n - current_sum

    for i in range(k - 1, 0, -1):
        if remaining >= i:
            sequence[i] += i
            remaining -= i

    if reduce(gcd, sequence) == target_gcd:
        return sequence
    else:
        return -1

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = find_sequence(n, k)

