import math
from sys import stdin, stdout

def find_sequence(n, k):
    if n < k or k == 1:
        return -1

    gcd = 1
    for i in range(1, k + 1):
        gcd = math.gcd(gcd, i)

    if n % gcd != 0:
        return -1

    sequence = [i * (n // gcd) for i in range(1, k + 1)]
    if sum(sequence) != n:
        return -1

    return sequence

def main():
    n, k = map(int, stdin.readline().split())
    result = find_sequence(n, k)
    if result == -1:
        stdout.write("-1\n")
    else:
        stdout.write(" ".join(map(str, result)) + "\n")

if __name__ == "__main__":
    main()
